insert into public.dialogues (key, speaker_external_id, source_path, source_metadata) select key, speaker_external_id, source_path, source_metadata from jsonb_to_recordset($seed$[{"key":"do_does_homework_q01_finish","speaker_external_id":"Main Gate Gaurd 1","source_path":"_registry\\dialogues\\do_does_homework.yaml","source_metadata":{}},{"key":"do_does_homework_q01_start","speaker_external_id":"Main Gate Gaurd 1","source_path":"_registry\\dialogues\\do_does_homework.yaml","source_metadata":{}}]$seed$::jsonb) as entries(key text, speaker_external_id text, source_path text, source_metadata jsonb) on conflict (key) do update set speaker_external_id = excluded.speaker_external_id, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.dialogue_lines (dialogue_id, locale, line_order, content, line_format) select dialogues.id, lines.locale, lines.line_order, lines.content, lines.line_format from jsonb_to_recordset($seed$[{"dialogue_key":"do_does_homework_q01_finish","locale":"he","line_order":0,"content":"ידעתי שתצליחו. אתם זוכרים את הסוד לבד, כמו שומרים אמיתיים, ומחר תעמדו איתנו בשער.","line_format":"plain_text"},{"dialogue_key":"do_does_homework_q01_finish","locale":"he","line_order":1,"content":"זכרו: I, you, we, they הולכים עם do. He, she, it הולכים עם does, ואחריו הפועל בלי s: Does he play? = האם הוא משחק?","line_format":"plain_text"},{"dialogue_key":"do_does_homework_q01_finish","locale":"he","line_order":2,"content":"כל הכבוד. עשיתם את שיעורי הבית לבד.","line_format":"plain_text"},{"dialogue_key":"do_does_homework_q01_start","locale":"he","line_order":0,"content":"שלום שוב. כל העיר מדברת עליכם - בזכותכם הקסם חזר לכל ארבע אבני הדיבור.","line_format":"plain_text"},{"dialogue_key":"do_does_homework_q01_start","locale":"he","line_order":1,"content":"מחר יום שוק, וכל השומרים רוצים שתעמדו איתנו בשער, כשומרים ליום אחד.","line_format":"plain_text"},{"dialogue_key":"do_does_homework_q01_start","locale":"he","line_order":2,"content":"אבל שומר אמיתי זוכר את סוד פעלי העזר לבד, בלי עזרה.","line_format":"plain_text"},{"dialogue_key":"do_does_homework_q01_start","locale":"he","line_order":3,"content":"היום אין שום דבר חדש. רק תראו לי מה אתם זוכרים. התיבה בחצר המזרקה מחכה לכם.","line_format":"plain_text"}]$seed$::jsonb) as lines(dialogue_key text, locale text, line_order integer, content text, line_format text) join public.dialogues on dialogues.key = lines.dialogue_key on conflict (dialogue_id, locale, line_order) do update set content = excluded.content, line_format = excluded.line_format;
